const data = $json.body.data;

// Extraer texto del mensaje (conversación directa o mensaje extendido)
const mensajeTexto = data.message?.conversation || 
                     data.message?.extendedTextMessage?.text || 
                     '';

// Extraer número de teléfono y JID
const remoteJid = data.key.remoteJid;
const telefono = remoteJid.replace('@s.whatsapp.net', '').replace('@g.us', '');
const nombreRemitente = data.pushName || 'Usuario';
const instancia = $json.body.instance || 'GDA_POS';

// Si el mensaje está vacío (ej. sticker o reacción sin texto), no procesar
if (!mensajeTexto || mensajeTexto.trim() === '') {
  return [];
}

return [{
  json: {
    chatInput: mensajeTexto,
    remoteJid: remoteJid,
    telefono: telefono,
    nombreRemitente: nombreRemitente,
    instancia: instancia,
    sessionId: remoteJid
  }
}];

const inputData = $('Extraer Datos WhatsApp').first().json;
const dbUser = $input.first()?.json || {};

return [{
  json: {
    chatInput: inputData.chatInput,
    remoteJid: inputData.remoteJid,
    telefono: inputData.telefono,
    nombreRemitente: inputData.nombreRemitente,
    instancia: inputData.instancia,
    sessionId: inputData.sessionId,
    usuario_id: dbUser.usuario_id || null,
    empresa_id: dbUser.empresa_id || null,
    empresa_nombre: dbUser.empresa_nombre || 'GDA POS',
    usuario_nombre: dbUser.usuario_nombre || inputData.nombreRemitente
  }
}];
